-- 000085_backfill_moves_is_derived_fourth_wave.down.sql
-- M14-03f: 第四波 14 キャラの is_derived backfill(CSV に載る code のみ UPDATE)
-- 本ファイルは cmd/seedgen が character_data/*.csv から生成した成果物(手編集しない)。
-- CSV で is_derived=true の code のみ UPDATE する(触れない行は既定値 false のまま正しく振る舞う
-- ＝ユーザー生成行〔画面18 追加・rush-variant 生成〕に触れない。CHANGE-069 §2.1-d/-e)。
-- 既存マイグレは非改変(新規連番で追加)。

-- ===== dhalsim =====
UPDATE moves SET is_derived = 0
WHERE character_id IN (SELECT c.id FROM characters c WHERE c.code = 'dhalsim' AND c.game_id IN (SELECT id FROM games WHERE code = 'sf6'))
